INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','prepositions-of-time','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"prepositions-of-time","title":"Prepositions of time","level":"A1","order":17,"summary":"Practise at, on, in and no preposition with unambiguous time expressions.","learningGoals":["At","On and in","No preposition"],"guidance":"Read the short rules and examples, then complete a 20-question session. Use feedback to explain each choice. Revisit the skill you missed before trying again.","rules":[{"title":"At","explanation":"Use at with clock times and expressions such as noon, midnight and dawn.","examples":["The gates open at 8:15.","We leave at sunrise."]},{"title":"On and in","explanation":"Use on with days and dates, including a named day plus a part of that day. Use in with months and with the morning, afternoon or evening.","examples":["on Thursday afternoon","in November"]},{"title":"No preposition","explanation":"Usually omit a time preposition before next, last, this or every, and before today, tomorrow and yesterday. Here, — means leave the gap empty.","examples":["The rehearsal is next week.","I will call tomorrow."]}],"tips":["Read the full context before choosing.","Check the explanation, including after a correct answer.","A passing practice session is useful feedback, not a language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v1","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-time","pcc-esol"],"assessment":"Practice only; levels are approximate teaching labels, not validated CEFR assessment."},"quizItems":[{"id":"090c1fe6-4d0d-5b79-afed-ace31446e1eb","topicSlug":"prepositions-of-time","level":"A1","prompt":"The training session starts ____ six o''clock.","choices":[{"id":"A","text":"—"},{"id":"B